export function decodeEnvelope(value:unknown):Envelope {if(typeof value!=="object"||value===null||!("event_type" in value)||typeof value.event_type!=="string")throw new TypeError("Event type required");validate(envelopeSchema,value.event_type,value);const e=value as Envelope;const rule=schema["x-events"][e.event_type];if(!rule||e.producer!==rule.producer||e.aggregate_type!==rule.aggregate_type)throw new TypeError("Event producer mismatch");const field=rule["x-aggregate-field"];if(field&&((e.payload as unknown as Record<string,unknown>)[field]!==e.aggregate_id))throw new TypeError("Payload aggregate mismatch");if((rule.encrypted||e.aggregate_type==="external_event")&&(e.aggregate_id!==e.event_id||BigInt(e.aggregate_version)!==1n))throw new TypeError("Independent aggregate mismatch");return e;}
export function parseEnvelope(text:string):Envelope{return decodeEnvelope(parseStrictJSON(text));}
export function stringifyEnvelope(value:Envelope):string{return stringifyStrictJSON(decodeEnvelope(value));}
